package com.aditya.fefo.controller; import com.aditya.fefo.dto.AuditDtos.AuditResponse; import com.aditya.fefo.service.AuditService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/audit-logs") public class AuditController {private final AuditService s;public AuditController(AuditService s){this.s=s;}@GetMapping @PreAuthorize("hasRole('ADMIN')") public List<AuditResponse> list(){return s.list();}}
